  function showStyleEditor() { const detail = app.querySelector('.fanfic-style-detail'); if (!detail || detail.querySelector('[data-fanfic-style-name-input]')) return; const editor = document.createElement('div'); editor.className = 'fanfic-style-new'; editor.innerHTML = '<label>文风名称<input data-fanfic-style-name-input type="text" maxlength="60" placeholder="例如：电影感悬疑"></label><label>文风具体内容<textarea data-fanfic-style-content-input rows="5" maxlength="5000" placeholder="详细描述节奏、语言、氛围、叙事方式、对话特点……"></textarea></label><div><button data-fanfic-save-style type="button">保存并使用</button><button data-fanfic-cancel-style type="button">取消</button></div>'; detail.append(editor); editor.querySelector('[data-fanfic-style-content-input]')?.focus(); }
  function saveSharedStyle(style) { const key = writingStyleCatalog().storageKey || 'ideal-machine-if-writing-styles'; let list = []; try { list = JSON.parse(localStorage.getItem(key) || '[]'); } catch {} if (!Array.isArray(list)) list = []; const old = list.find(item => item.name === style.name); const next = { id: old?.id || uid('fanfic-style'), name: style.name, prompt: style.content }; localStorage.setItem(key, JSON.stringify([...list.filter(item => item.name !== style.name), next].slice(-40))); }
