  function deleteFanficStyles(names) { const targets = new Set(names); state.styles = (state.styles || []).filter(item => !targets.has(item.name)); const key = writingStyleCatalog().storageKey || 'ideal-machine-if-writing-styles'; try { const list = JSON.parse(localStorage.getItem(key) || '[]'); if (Array.isArray(list)) localStorage.setItem(key, JSON.stringify(list.filter(item => !targets.has(item?.name)))); } catch {} const firstBuiltIn = Object.values(writingStyleCatalog().styles || {})[0] || '自然细腻'; if (targets.has(draft.style)) { draft.style = firstBuiltIn; draft.styleContent = styleContent(firstBuiltIn, ''); styleNotice = `已恢复为内置文风：${firstBuiltIn}`; } save(); render(); }
