  function openFanficGenerationPresetEditor(item = null) { const editor = app.querySelector('[data-fanfic-generation-preset-editor]'); if (!editor) return; editor.dataset.editId = item?.id || ''; const name = editor.querySelector('[data-fanfic-generation-preset-name]'); const prompt = editor.querySelector('[data-fanfic-generation-preset-prompt]'); const input = app.querySelector('[data-fanfic-generation-preset]'); if (name) name.value = item?.name || ''; if (prompt) prompt.value = input?.value.trim() || item?.prompt || fanficGenerationPresetTemplate(); editor.hidden = false; name?.focus(); }
