  function settingField(label, key, content) { return `<label class="fanfic-setting-field"><span>${label}</span>${content.replace('<FIELD>', `data-fanfic-setting="${key}"`)}</label>`; }

  function clearLongPress() { if (longPressTimer) window.clearTimeout(longPressTimer); longPressTimer = null; }
  function openApp(fromCreativeFolder = false) { openedFromCreativeFolder = Boolean(fromCreativeFolder); state = readState(); page = 'home'; activeId = ''; editingId = ''; shareStoryId = ''; shareContactId = ''; homeSearchOpen = false; homeSearchQuery = ''; homeStatusFilter = '全部'; homeMenuOpen = false; homeRowMenuId = ''; clearLongPress(); shell?.classList.remove('is-open'); shell?.setAttribute('aria-hidden', 'true'); folder?.classList.remove('is-open'); folder?.setAttribute('aria-hidden', 'true'); app.classList.add('is-open'); app.setAttribute('aria-hidden', 'false'); render(); }
  function clearReaderIdleTimer() { if (readerIdleTimer) { window.clearTimeout(readerIdleTimer); readerIdleTimer = null; } }
  function scheduleReaderDockIdle() { clearReaderIdleTimer(); }
