    const manageBar = managingBooks ? `<div class="fanfic-home-manage"><span>选择要管理的作品</span><div><button data-fanfic-delete-selected-stories type="button">删除已选</button><button data-fanfic-manage-books type="button">完成</button></div></div>` : '';
    const empty = !state.stories.length ? `<div class="fanfic-home-empty">${homeIcon('empty')}<h2>还没有故事</h2><p>从一个想法开始，写下属于你的另一个世界。</p><button data-fanfic-new type="button">新建故事</button></div>` : `<div class="fanfic-home-search-empty" data-fanfic-home-search-empty hidden><h2>没有找到作品</h2><p>换一个关键词试试。</p></div>`;
